const {
  Document, Packer, Paragraph, TextRun, HeadingLevel, AlignmentType,
  Table, TableRow, TableCell, WidthType, ShadingType, BorderStyle,
  LevelFormat, convertInchesToTwip
} = require('docx');
const fs = require('fs');

const GOLD = "8A6E3B";
const INK = "1B1B1B";
const GREY = "555555";

const H = (t) => new Paragraph({
  heading: HeadingLevel.HEADING_1,
  spacing: { before: 320, after: 140 },
  children: [new TextRun({ text: t, bold: true, size: 28, color: GOLD, font: "Georgia" })]
});

const H2 = (t) => new Paragraph({
  heading: HeadingLevel.HEADING_2,
  spacing: { before: 220, after: 100 },
  children: [new TextRun({ text: t, bold: true, size: 23, color: INK, font: "Georgia" })]
});

const P = (t, opts = {}) => new Paragraph({
  spacing: { after: 110, line: 300 },
  alignment: opts.align,
  children: [new TextRun({ text: t, size: 21, color: opts.color || INK, font: "Calibri", italics: opts.italics, bold: opts.bold })]
});

const B = (t) => new Paragraph({
  numbering: { reference: "bullets", level: 0 },
  spacing: { after: 70, line: 290 },
  children: [new TextRun({ text: t, size: 21, color: INK, font: "Calibri" })]
});

const rule = () => new Paragraph({
  spacing: { before: 100, after: 160 },
  border: { bottom: { color: GOLD, style: BorderStyle.SINGLE, size: 6 } },
  children: [new TextRun("")]
});

const TW = 9360;
function cell(text, { bold = false, shade = null, width, align = AlignmentType.LEFT, color = INK } = {}) {
  return new TableCell({
    width: { size: width, type: WidthType.DXA },
    shading: shade ? { type: ShadingType.CLEAR, fill: shade, color: "auto" } : undefined,
    margins: { top: 90, bottom: 90, left: 130, right: 130 },
    children: [new Paragraph({
      alignment: align,
      children: [new TextRun({ text, bold, size: 20, font: "Calibri", color })]
    })]
  });
}
function table(cols, rows, headerFill = "F3EFE7") {
  return new Table({
    width: { size: TW, type: WidthType.DXA },
    columnWidths: cols.map(c => c.w),
    rows: [
      new TableRow({
        tableHeader: true,
        children: cols.map(c => cell(c.h, { bold: true, shade: headerFill, width: c.w, align: c.align }))
      }),
      ...rows.map(r => new TableRow({
        children: r.map((v, i) => cell(v, { width: cols[i].w, align: cols[i].align, bold: i === 0 ? false : false }))
      }))
    ]
  });
}

const doc = new Document({
  numbering: {
    config: [{
      reference: "bullets",
      levels: [{
        level: 0, format: LevelFormat.BULLET, text: "\u2022", alignment: AlignmentType.LEFT,
        style: { paragraph: { indent: { left: convertInchesToTwip(0.35), hanging: convertInchesToTwip(0.2) } } }
      }]
    }]
  },
  sections: [{
    properties: {
      page: {
        size: { width: 12240, height: 15840 },
        margin: { top: 1440, bottom: 1440, left: 1440, right: 1440 }
      }
    },
    children: [
      // Cover
      new Paragraph({ spacing: { before: 1600, after: 60 }, alignment: AlignmentType.CENTER,
        children: [new TextRun({ text: "THE LUXORA COLLECTIVE", bold: true, size: 24, color: GOLD, font: "Georgia", characterSpacing: 60 })] }),
      new Paragraph({ spacing: { after: 500 }, alignment: AlignmentType.CENTER,
        children: [new TextRun({ text: "Revenue Growth Partners for Medical Aesthetics", size: 19, color: GREY, font: "Calibri", italics: true })] }),
      new Paragraph({ spacing: { after: 120 }, alignment: AlignmentType.CENTER,
        children: [new TextRun({ text: "Launch Foundation Proposal", bold: true, size: 44, color: INK, font: "Georgia" })] }),
      new Paragraph({ spacing: { after: 400 }, alignment: AlignmentType.CENTER,
        children: [new TextRun({ text: "Market Blueprint, Procedure Feasibility, and Guided Services Menu", size: 22, color: GREY, font: "Calibri" })] }),
      rule(),
      new Paragraph({ spacing: { after: 60 }, alignment: AlignmentType.CENTER,
        children: [new TextRun({ text: "Prepared for Riza Hernandez", bold: true, size: 22, color: INK, font: "Calibri" })] }),
      new Paragraph({ spacing: { after: 60 }, alignment: AlignmentType.CENTER,
        children: [new TextRun({ text: "Boutique Hotel Wellness and Medical Aesthetics Concept, California", size: 20, color: GREY, font: "Calibri" })] }),
      new Paragraph({ spacing: { after: 900 }, alignment: AlignmentType.CENTER,
        children: [new TextRun({ text: "Prepared by Bethany Anne, Co-Founder and Chief Executive Officer", size: 20, color: GREY, font: "Calibri" })] }),
      new Paragraph({ alignment: AlignmentType.CENTER,
        children: [new TextRun({ text: "theluxoracollective.co", size: 19, color: GOLD, font: "Calibri" })] }),

      // 1
      H("Where You Are Today"),
      P("You are four to five months from opening a two-concept space inside a boutique hotel conversion. One space carries recovery and longevity, meaning cold plunge, sauna, and hyperbaric. The other carries medical aesthetics under a medical director, meaning injectables, energy-based devices, and CO2 resurfacing."),
      P("You have the location. You have feasibility on the recovery and wellness side. What you do not yet have, in your own words, is the answer to the question everything else depends on: which treatments do you launch with, in what order, at what price, and what do they return?"),
      P("Until that question is answered, you cannot set a build budget. You cannot raise against a build budget. You cannot recruit a medical director against a service list that does not exist yet. And you cannot evaluate a marketing agency that is quoting you five thousand dollars a month in ad spend without knowing whether your market requires five thousand, fifteen hundred, or ten thousand."),
      P("That is the sequence problem. This proposal solves it."),

      H("What We Are Not Proposing"),
      P("I want to be direct with you, because you were direct with us."),
      B("We are not proposing our standard ninety day Growth Engine. You are pre-revenue. That program is built to recover revenue that is already leaking, and you do not have revenue to leak yet."),
      B("We are not proposing marketing. You do not need marketing. You need a service list first."),
      B("We are not proposing that you retain us before you have a medical director, and we will not implement anything that depends on scope of practice until that role is filled."),
      P("What we are proposing is the research and architecture layer that has to exist before any of the above becomes a responsible use of your capital. It is the smallest useful engagement, not the largest one we could sell you.", { italics: true }),

      H("The Launch Foundation"),
      P("Three deliverables, built in sequence, each one feeding the next. Approximately three to four weeks from the day we receive your onboarding checklist."),

      H2("Deliverable One: The Market Blueprint"),
      P("Most agencies hand you a template. We build the map of your actual ground."),
      B("Competitive census of medical spas, wellness studios, recovery lounges, and longevity clinics within your primary and secondary draw radius, plus a statewide read on where the category is moving in California."),
      B("For each meaningful competitor: service mix, published pricing, membership structure, positioning language, review sentiment, and where they are visibly weak."),
      B("Demographic and psychographic profile of your actual catchment, including age distribution, household income bands, spend behavior, and the gap between who lives there and who is currently being served."),
      B("Estimated true cost of customer acquisition in your zip code, which is the number that tells you what ad spend is defensible and what is a sales pitch."),
      B("Saturation analysis by service category, so you know which treatments are commoditized in your area and which are underserved."),
      B("A positioning recommendation for the hotel-attached concept specifically, including how the wellness side and the medical side should relate to each other in the eyes of the market."),
      P("Delivered as a detailed written analysis, not a one-page summary. If there are factors specific to your concept that you want researched, we add them to scope at no cost.", { italics: true }),

      H2("Deliverable Two: Procedure and Device Feasibility Map"),
      P("This is the piece you asked for and the piece nobody else is offering you. You are a planner. You want to see the bottom line first and work backward. This is that document."),
      B("Every candidate treatment, medical and wellness, scored against demand in your market, capital requirement, room and staff time consumed, consumable and disposable cost, and licensure requirement under California scope of practice."),
      B("Capital cost modeling for equipment, including purchase against lease against certified pre-owned, with the true monthly carry on each."),
      B("Revenue per treatment room hour for each service, which is the metric that determines whether a treatment earns its square footage in a twelve hundred square foot space."),
      B("A ranked launch sequence: Phase One at open, Phase Two at the sixty to ninety day mark, Phase Three at the point where utilization justifies the next capital outlay."),
      B("Break-even modeling per phase, including estimated months to break-even at conservative, base, and strong demand assumptions."),
      B("Recommended treatment room count and layout logic for the two spaces, so you do not build six rooms and staff four."),
      P("The output is a defensible capital number. That is what you take to your raise.", { bold: true }),

      H2("Deliverable Three: Guided Services Menu and Pricing Architecture"),
      P("Once we know what you launch with and what it returns, we build the menu that a client actually sees and a staff member actually sells."),
      B("Full service menu for the medical aesthetics side and the recovery and longevity side, written in client-facing language."),
      B("Pricing architecture calibrated to your market, not a national average, with margin verified against the consumable and time costs from Deliverable Two."),
      B("The cross-over layer. Your injectable client and your recovery client should be the same client. We build the connective tissue between the two spaces deliberately rather than hoping it happens."),
      B("Bundling logic and good, better, best tiering so that the menu itself does part of the selling."),
      B("A one-page pricing rationale you can hand to a medical director candidate or an investor and have it hold up under questioning."),

      // Investment
      H("Investment"),
      P("These are priced to be taken individually or as a bundle. The bundle is what I would recommend, because the second and third deliverables are considerably weaker without the market data underneath them."),
      table(
        [{ h: "Deliverable", w: 4600, align: AlignmentType.LEFT },
         { h: "Timeline", w: 2360, align: AlignmentType.LEFT },
         { h: "Investment", w: 2400, align: AlignmentType.RIGHT }],
        [
          ["Market Blueprint", "72 hours from checklist", "$1,500"],
          ["Procedure and Device Feasibility Map", "10 to 14 days", "$2,500"],
          ["Guided Services Menu and Pricing Architecture", "7 to 10 days", "$1,500"],
          ["Launch Foundation Bundle (all three)", "3 to 4 weeks", "$4,500"],
        ]
      ),
      new Paragraph({ spacing: { after: 120 } , children: [new TextRun("")]}),
      P("The bundle carries a one thousand dollar reduction against the sum of the parts, and it includes two working sessions with me directly to walk the findings rather than a document handoff.", { italics: true }),

      // Add-ons
      H("Optional Additions"),
      P("None of the below is required. Each becomes relevant at a specific trigger point, and I have noted the trigger so you can time them correctly rather than buy them early."),
      table(
        [{ h: "Addition", w: 3300, align: AlignmentType.LEFT },
         { h: "When it becomes relevant", w: 3900, align: AlignmentType.LEFT },
         { h: "Investment", w: 2160, align: AlignmentType.RIGHT }],
        [
          ["Membership and Package Architecture", "Once the service menu is locked and pricing is verified", "$2,000"],
          ["SOP Starter Set and Master Index", "30 to 60 days before doors open", "$1,800"],
          ["KPI Dashboard and Owner Reporting Cadence", "At or just before open", "$900"],
          ["Front Desk and Consultation Sales Training", "Once staff is hired, 2 to 3 weeks pre-open", "$2,500"],
          ["Medical Director Structuring Brief (California)", "Before you sign a medical director agreement", "$750"],
          ["Advisory Introductions", "Immediately, at your request", "No charge"],
          ["Private Consulting with Bethany", "Monthly retainer, limited availability", "By arrangement"],
        ]
