      new Paragraph({ spacing: { after: 140 }, children: [new TextRun("")] }),
      P("If you complete the Launch Foundation and elect to move into a Growth Engine within twelve months, the full Launch Foundation investment is credited against the program fee.", { bold: true }),

      H("What We Do Not Do"),
      B("We do not do business branding or identity design. We have a partner who does."),
      B("We do not post to your social accounts. We train your team to do it, because outsourcing that is usually a waste of your money."),
      B("We do not sell you ad spend before we know what your market costs."),
      B("We do not take clients we cannot help. If, after the Market Blueprint, the right answer is that you need a boots-on-the-ground launch consultant rather than us, I will tell you that and point you at the right person."),

      H("Sequence and Next Steps"),
      P("The order matters more than the speed."),
      new Paragraph({ numbering: { reference: "bullets", level: 0 }, spacing: { after: 70 }, children: [new TextRun({ text: "Confirm which deliverables you want. If it is the bundle, we send a short onboarding checklist the same day.", size: 21, font: "Calibri" })] }),
      new Paragraph({ numbering: { reference: "bullets", level: 0 }, spacing: { after: 70 }, children: [new TextRun({ text: "Market Blueprint returns within 72 hours of the completed checklist. We review it together on a call.", size: 21, font: "Calibri" })] }),
      new Paragraph({ numbering: { reference: "bullets", level: 0 }, spacing: { after: 70 }, children: [new TextRun({ text: "Feasibility Map follows. You now have a capital number and a phased build plan.", size: 21, font: "Calibri" })] }),
      new Paragraph({ numbering: { reference: "bullets", level: 0 }, spacing: { after: 70 }, children: [new TextRun({ text: "Services Menu and Pricing Architecture follows. You now have something to show a medical director candidate and an investor.", size: 21, font: "Calibri" })] }),
      new Paragraph({ numbering: { reference: "bullets", level: 0 }, spacing: { after: 70 }, children: [new TextRun({ text: "You recruit your medical director and open your raise against real numbers.", size: 21, font: "Calibri" })] }),
      new Paragraph({ numbering: { reference: "bullets", level: 0 }, spacing: { after: 160 }, children: [new TextRun({ text: "We reconvene sixty days out from open and decide together whether a Growth Engine is the right next step.", size: 21, font: "Calibri" })] }),

      rule(),
      P("You said you are a planner by trade, that you work backward from the bottom line. So do we. Everything above exists to put a defensible number in front of you before you spend a dollar you cannot get back.", { italics: true }),
      new Paragraph({ spacing: { before: 300, after: 60 }, children: [new TextRun({ text: "Bethany Anne", bold: true, size: 22, font: "Georgia", color: INK })] }),
      P("Co-Founder and Chief Executive Officer, The Luxora Collective", { color: GREY }),
      P("theluxoracollective.co", { color: GOLD }),
    ]
  }]
